\title{Wetware Computation: Iterated Dynamics and the Information Cost of Determinism}
\author{Aristotle}
\date{2026-07-11}

\begin{document}

\begin{abstract}
We develop a minimal mathematical model of \emph{wetware} computation --
biological computation viewed as a discrete dynamical system -- and use it to
prove a cross-domain \textbf{connector} relating enumerative combinatorics to
asymptotic real analysis. A wetware system is a state space $S$ together with a
step map $\step : S \to S$; running the system means iterating the step map, and
this iteration obeys a flow (semigroup) law that makes it an action of
$(\N, +)$. We prove three results. First, \emph{finite-data universality}:
every function $f : X \to Y$ is computed by some wetware system equipped with an
encoder and a decoder in a single step -- the finite analogue of the
Turing-completeness of neural networks. Second, \emph{eventual periodicity}: on
any finite state space every orbit revisits a state, hence is eventually
periodic. Third, and central, an \emph{energy connector}: measuring the
specification cost of a machine on $n$ neurons by the Shannon information (base-2
logarithm) of its configuration count, a deterministic transition map costs
exactly $n \log_2 n$ bits while an arbitrary binary connection matrix costs
exactly $n^2$ bits. We prove the strict separation $n \log_2 n < n^2$ for all
$n \ge 1$ and the asymptotic separation $\tfrac{n \log_2 n}{n^2} \to 0$: the
information cost of \emph{determinism} is asymptotically negligible next to that
of arbitrary \emph{connectivity}.
\end{abstract}

\maketitle

\section{Introduction}

The brain is an existence proof that matter can compute, and a remarkably
economical one. To reason precisely about \emph{why}, we abstract away substrate:
a computer is a rule that maps a total state to its successor, and computation is
the iteration of that rule. We call an instance a \textbf{wetware system}.

From this single primitive we extract three kinds of statement, each from a
different mathematical tradition: an \emph{expressiveness} result (the model
computes any function on finite data), a \emph{limitative} result (finite
machines must eventually cycle), and a \emph{resource} result (deterministic
dynamics is far cheaper to specify than arbitrary connectivity). The third is the
paper's connector: it links the counting of hardware configurations to the
asymptotic behavior of a ratio, mediated by a single logarithm.

\section{The model}

\begin{definition}[Wetware system]
A \emph{wetware system} on a type $S$ consists of a single \textbf{step map}
$\step : S \to S$. The type $S$ is the \emph{state space} and $\step$ is the
\emph{one-step transition}.
\end{definition}

\begin{definition}[Run]
The \emph{run} of a wetware system for $t \in \N$ steps from $x \in S$ is the
$t$-fold iterate $\run(t,x) := \step^{[t]}(x)$, where $\step^{[0]} = \mathrm{id}$
and $\step^{[t+1]} = \step \circ \step^{[t]}$.
\end{definition}

Immediately $\run(0,x) = x$, $\run(1,x) = \step(x)$, and $\run(t+1,x) =
\step(\run(t,x))$.

\begin{theorem}[Flow / semigroup law]
For all $s,t \in \N$ and $x \in S$,
\[ \run(s+t, x) = \run\big(s, \run(t,x)\big). \]
\end{theorem}

\begin{proof}
Iteration is additive in the exponent, $\step^{[s+t]} = \step^{[s]} \circ
\step^{[t]}$; apply both sides to $x$.
\end{proof}

The flow law makes a wetware system a (left) action of the monoid $(\N,+)$ on
$S$: clock time composes additively and the future depends only on the present
state.

\section{Finite-data universality}

\begin{definition}[Computation]
Let $W$ be a wetware system on $S$, let $\mathrm{enc} : X \to S$ and $\mathrm{dec}
: S \to Y$, and let $T \in \N$. Then $W$ \emph{computes} $f : X \to Y$ in $T$
steps if $\mathrm{dec}(\run(T, \mathrm{enc}(x))) = f(x)$ for all $x \in X$.
\end{definition}

\begin{theorem}[Finite-data universality]
For every $f : X \to Y$ there exist a state space $S'$, a wetware system $W$ on
$S'$, an encoder $\mathrm{enc}$, and a decoder $\mathrm{dec}$ such that $W$
computes $f$ in a single step ($T = 1$).
\end{theorem}

\begin{proof}
Let $S' = X \sqcup Y$, whose points are tagged as a pending input $\iota_X(x)$ or
a produced output $\iota_Y(y)$. Set $\mathrm{enc}(x) = \iota_X(x)$; let $\step$
send $\iota_X(x) \mapsto \iota_Y(f(x))$ and fix each $\iota_Y(y)$; let
$\mathrm{dec}$ send $\iota_X(x) \mapsto f(x)$ and $\iota_Y(y) \mapsto y$. Then
$\run(1, \mathrm{enc}(x)) = \iota_Y(f(x))$, and decoding yields $f(x)$.
\end{proof}

\begin{remark}
This is the finite-state analogue of the Turing-completeness of neural networks:
the model places no restriction on realizable functions. Real limits arise from
resources, not expressiveness; a genuine unbounded-tape simulation requires an
unbounded state space.
\end{remark}

\section{Eventual periodicity}

\begin{theorem}[Eventual periodicity of finite orbits]
Let $S$ be finite and $W$ a wetware system on $S$. For every $x \in S$ there
exist $i < j$ in $\N$ with $\run(i,x) = \run(j,x)$.
\end{theorem}

\begin{proof}
The orbit map $k \mapsto \run(k,x)$ sends the infinite set $\N$ into the finite
set $S$, so it cannot be injective; two distinct indices collide, and ordering
them gives $i < j$.
\end{proof}

\begin{corollary}
With $p = j - i > 0$, for all $k \ge i$ we have $\run(k+p, x) = \run(k,x)$: the
orbit is eventually periodic with period dividing $p$. A finite deterministic
wetware system cannot produce aperiodic behavior by pure iteration.
\end{corollary}

\begin{proof}
By the flow law and $\run(i,x) = \run(i+p,x)$, induction on $k - i$ propagates
the coincidence: $\run(k+p,x) = \run(k-i, \run(i+p,x)) = \run(k-i, \run(i,x)) =
\run(k,x)$.
\end{proof}

\section{The energy connector}

\begin{definition}[Configurations]
On $n$ neurons, a \textbf{wetware} configuration is a deterministic transition map
$\Fin\,n \to \Fin\,n$, and a \textbf{silicon} configuration is an arbitrary binary
connection matrix $\Fin\,n \to \Fin\,n \to \Bool$.
\end{definition}

\begin{lemma}[Counts]
$\#\{\text{wetware configs}\} = n^n$ and $\#\{\text{silicon configs}\} =
2^{(n^2)}$.
\end{lemma}

\begin{proof}
There are $n^n$ functions from an $n$-element set to itself, and $2^{n^2}$
Boolean-valued functions on the $n^2$ ordered pairs.
\end{proof}

\begin{definition}[Energy]
The \emph{energy} of a discipline on $n$ neurons is the number of bits needed to
name one configuration:
\[ \wE(n) = \log_2\!\big(n^n\big), \qquad \sE(n) = \log_2\!\big(2^{(n^2)}\big). \]
\end{definition}

\begin{theorem}[Closed forms]
For all $n$, $\wE(n) = n \log_2 n$ and $\sE(n) = n^2$.
\end{theorem}

\begin{proof}
Using $\log_2(a^b) = b\log_2 a$: $\log_2(n^n) = n\log_2 n$ and $\log_2(2^{n^2}) =
n^2 \log_2 2 = n^2$.
\end{proof}

\begin{theorem}[Wetware beats silicon]
For every integer $n \ge 1$, $\wE(n) < \sE(n)$; equivalently $n \log_2 n < n^2$.
\end{theorem}

\begin{proof}
For $n \ge 1$ we have $n < 2^n$. Applying the strictly increasing $\log_2$ gives
$\log_2 n < n$, and multiplying by $n > 0$ yields $n \log_2 n < n^2$.
\end{proof}

\begin{lemma}[Analytic core]
$\displaystyle \lim_{x \to \infty} \frac{\log_2 x}{x} = 0.$
\end{lemma}

\begin{proof}
Write $\log_2 x = \ln x / \ln 2$; since $\ln x / x \to 0$, dividing by the
constant $\ln 2$ gives the claim.
\end{proof}

\begin{theorem}[Asymptotic separation -- the connector]
$\displaystyle \lim_{n \to \infty} \frac{\wE(n)}{\sE(n)} = 0.$
\end{theorem}

\begin{proof}
For $n \ge 1$, $\dfrac{\wE(n)}{\sE(n)} = \dfrac{n \log_2 n}{n^2} =
\dfrac{\log_2 n}{n} \to 0$ by the preceding lemma.
\end{proof}

The two ends of the bridge belong to different fields: the identities $n^n$ and
$2^{n^2}$ are enumerative combinatorics, while $\log_2 n / n \to 0$ is asymptotic
analysis. The information cost of determinism is an asymptotically vanishing
fraction of the cost of arbitrary connectivity.

\section{Applications and future work}

Applications include neuromorphic hardware budgeting (favoring sparse
deterministic transition fabrics over dense connectivity), model compression (a
deterministic routing layer stores in $n\log_2 n$ bits against $n^2$ for a dense
adjacency layer), and a dynamical-systems view of iterated learning updates.

Future directions: (1) full Turing-completeness via an unbounded state space
simulating a register/stack machine; (2) two-sided $\Theta(n\log n)$ coding
bounds via Kraft's inequality; (3) continuous dynamics on smooth manifolds, with
the step map a time-1 flow; (4) a careful, conditional treatment of the
``super-Turing'' hypothesis isolating unbounded real precision as the true
resource; (5) attractor geometry, bounding cycle lengths and counting fixed
points of the state graph.

\section{Conclusion}

A computer is an iterated step map. This single idea is universal on finite data,
necessarily periodic when finite, and reveals that determinism is a profound
information bargain: $n \log_2 n$ bits against $n^2$, a gap that widens without
bound. Enumerative combinatorics and asymptotic analysis, joined by a logarithm,
agree: constraint is cheap.

\end{document}

