"""Demo: The flow (semigroup) law of iterated computation."""
from typing import Callable, TypeVar
S = TypeVar("S")

def run(step: Callable[[S], S], t: int, x: S) -> S:
    state = x
    for _ in range(t):
        state = step(state)
    return state

def verify_flow_law(step: Callable[[int], int], modulus: int, bound: int) -> bool:
    """Check run(s+t, x) == run(s, run(t, x)) exhaustively."""
    for s in range(bound):
        for t in range(bound):
            for x in range(modulus):
                if run(step, s + t, x) != run(step, s, run(step, t, x)):
                    return False
    return True

if __name__ == "__main__":
    step: Callable[[int], int] = lambda s: (s + 5) % 12
    print("Flow law holds:", verify_flow_law(step, 12, 6))

"""Demo: Finite-data universality — compute any function in one step."""
from typing import Callable, Dict, List, Tuple, TypeVar
X = TypeVar("X"); Y = TypeVar("Y")

def build_universal_wetware(f: Callable[[int], int], domain: List[int]):
    ftab: Dict[int, int] = {x: f(x) for x in domain}
    def step(state: Tuple[str, int]) -> Tuple[str, int]:
        tag, val = state
        return ("out", ftab[val]) if tag == "in" else ("out", val)
    enc: Callable[[int], Tuple[str, int]] = lambda x: ("in", x)
    dec: Callable[[Tuple[str, int]], int] = lambda st: st[1]
    return step, enc, dec

def run(step, t, x):
    for _ in range(t):
        x = step(x)
    return x

if __name__ == "__main__":
    domain = list(range(8))
    f: Callable[[int], int] = lambda x: (x * x + 3) % 8
    step, enc, dec = build_universal_wetware(f, domain)
    ok = all(dec(run(step, 1, enc(x))) == f(x) for x in domain)
    print("Universality verified:", ok)

"""Demo: The energy connector — n*log2 n vs n^2 and the vanishing ratio."""
from math import log2
from typing import List, Tuple

def wetware_energy(n: int) -> float:
    return n * log2(n) if n > 0 else 0.0

def silicon_energy(n: int) -> float:
    return float(n * n)

def energy_table(ns: List[int]) -> List[Tuple[int, float, float, float]]:
    rows = []
    for n in ns:
        w, s = wetware_energy(n), silicon_energy(n)
        rows.append((n, w, s, w / s))
    return rows

if __name__ == "__main__":
    for n, w, s, r in energy_table([2, 8, 64, 1024, 10**6, 10**9]):
        print(f"n={n:>10}  wetware={w:>16.2f}  silicon={s:>10.2e}  ratio={r:.3e}")

