function FIND_CYCLE(step, start):
    seen <- empty map from state to time
    state <- start ; t <- 0
    while state not in seen:
        seen[state] <- t
        state <- step(state)
        t <- t + 1
    mu  <- seen[state]      # onset of the cycle
    lam <- t - mu           # period
    return (mu, lam)        # run(mu) == run(mu + lam)

function ENERGY_REPORT(n):
    require n >= 1
    wetware <- n * log2(n)     # = log2(n^n)
    silicon <- n * n           # = log2(2^(n^2))
    return { wetware, silicon,
             difference = silicon - wetware,
             ratio      = wetware / silicon }

function SYNTHESIZE_WETWARE(f, domain):
    table <- { x : f(x) for x in domain }
    function step((tag, val)):
        if tag = 'in':  return ('out', table[val])
        else:           return ('out', val)
    enc(x) := ('in', x)
    dec((tag, val)) := val
    return (step, enc, dec)
